async function toolAction(action,id){try{await post('tools/'+action,{id});await loadConnections(false);}catch(e){report(e)}}
async function previewAsset(id){if(previewUrl)URL.revokeObjectURL(previewUrl);const response=await fetch('/api/asset?id='+id,{headers:{'X-Office-Token':state.token}});if(!response.ok)throw Error('Não foi possível abrir a mídia.');const blob=await response.blob();previewUrl=URL.createObjectURL(blob);$('#mediaPreview').hidden=false;const element=document.createElement(blob.type.startsWith('audio')?'audio':blob.type.startsWith('video')?'video':'img');element.src=previewUrl;element.alt='Mídia gerada';if(blob.type.startsWith('video')||blob.type.startsWith('audio'))element.controls=true;$('#mediaPreviewBody').replaceChildren(element);}
$('#closeMediaPreview').onclick=()=>{$('#mediaPreview').hidden=true;$('#mediaPreviewBody').replaceChildren();if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;};
function showConnectionTab(name){document.querySelectorAll('.con-section').forEach(p=>p.hidden=p.id!=='con_'+name);document.querySelectorAll('[data-con-tab]').forEach(b=>b.classList.toggle('active',b.dataset.conTab===name));}
document.querySelectorAll('[data-con-tab]').forEach(b=>b.onclick=()=>showConnectionTab(b.dataset.conTab));$('#goServers').onclick=()=>{openDialog('connections');showConnectionTab('setup');};

const textPresets={freellm:{base:'http://127.0.0.1:3001/v1',model:'auto',key:'FREELLM_API_KEY'},gemini:{base:'https://generativelanguage.googleapis.com/v1beta/openai',model:'auto-gemini-free',key:'GEMINI_API_KEY'},groq:{base:'https://api.groq.com/openai/v1',model:'openai/gpt-oss-20b',key:'GROQ_API_KEY'},openrouter:{base:'https://openrouter.ai/api/v1',model:'openrouter/free',key:'OPENROUTER_API_KEY'}};
$('#applyFreeProvider').onclick=()=>{const p=textPresets[$('#freeProvider').value];$('#agentInherit').checked=false;setAgentInheritance();$('#agentBase').value=p.base;$('#agentModel').value=p.model;$('#agentModel').readOnly=$('#freeProvider').value==='gemini';$('#agentKey').value=p.key;$('#agentTokens').value=$('#freeProvider').value==='freellm'?0:2600;report({message:'Configuração preenchida. Salve o funcionário e teste a conexão.'});};
function loadGeneralSettings(){if(!connectionData)return;const s=connectionData.settings,p=Object.entries(textPresets).find(([k,v])=>v.base===s.text_base_url)?.[0]||'gemini';$('#generalProvider').value=p;$('#generalModel').value=p==='gemini'?'auto-gemini-free':s.text_model||textPresets[p].model;$('#generalModel').readOnly=p==='gemini';$('#generalModel').hidden=p==='gemini';$('#generalModelLabel').hidden=p==='gemini';$('#generalKey').value=s.text_key||textPresets[p].key;$('#generalTokens').value=s.text_max_tokens??2600;$('#generalTokens').min=p==='freellm'?'0':'128';$('#generalTokens').max=p==='freellm'?'65536':'8000';$('#textDailyLimit').value=s.text_daily_limit||400;$('#generalStatus').textContent=s.text_mode==='api'?'Modelo geral ativo: '+s.text_model+'. Configurações próprias de especialistas continuam valendo.':'Modelo geral visual ainda não ativado. Salve a chave e clique em Ativar modelo geral.';}
$('#generalProvider').onchange=()=>{const p=textPresets[$('#generalProvider').value];$('#generalModel').value=p.model;$('#generalModel').readOnly=$('#generalProvider').value==='gemini';$('#generalModel').hidden=$('#generalProvider').value==='gemini';$('#generalModelLabel').hidden=$('#generalProvider').value==='gemini';$('#generalKey').value=p.key;$('#generalTokens').min=$('#generalProvider').value==='freellm'?'0':'128';$('#generalTokens').max=$('#generalProvider').value==='freellm'?'65536':'8000';$('#generalTokens').value=$('#generalProvider').value==='freellm'?0:2600;renderCredentialLinks();};
$('#generalSettings').onsubmit=async e=>{e.preventDefault();const p=textPresets[$('#generalProvider').value];try{await post('integrations/settings',{settings:{text_mode:'api',text_base_url:p.base,text_model:$('#generalProvider').value==='gemini'?'auto-gemini-free':$('#generalModel').value,text_key:$('#generalKey').value,text_daily_limit:$('#textDailyLimit').value,text_max_tokens:$('#generalTokens').value}});await loadConnections(false);loadGeneralSettings();renderCredentialLinks();markConnectionFormSaved('generalSettings');report({message:'IA geral ativada. Funcionários que herdam o modelo geral usarão esta configuração na próxima tarefa.'});}catch(e){report(e)}};

$('#quickGemini').onsubmit=async e=>{e.preventDefault();const button=$('#quickGeminiButton');button.disabled=true;button.textContent='Conectando…';setSetupResult('quickGeminiResult','loading','Consultando modelos disponíveis e testando sua chave. Aguarde a confirmação.');$('#setupTryChat').hidden=true;setSetupStep(3);try{const target=$('#setupEmployee').value;const employee=target==='team'?null:target!==''?+target:selected;const result=await post('integrations/gemini/connect',{key:$('#quickGeminiKey').value.trim(),employee});$('#quickGeminiKey').value='';$('#quickGeminiKey').type='password';$('#toggleGeminiKey').textContent='Mostrar';$('#toggleGeminiKey').setAttribute?.('aria-pressed','false');markConnectionFormSaved('quickGemini');setSetupResult('quickGeminiResult','success',result.message);$('#setupTryChat').hidden=false;await loadConnections(true);report({message:'IA conectada. Você já pode começar.'});window.officeWelcomeConnected?.();}catch(e){setSetupResult('quickGeminiResult','error',friendlySetupError(e.message));setSetupStep(2);report(e);}finally{button.disabled=false;button.textContent='Conectar Gemini e testar →';}};

const connectionStatusLabels={queued:'Na fila',running:'Em execução',waiting:'Aguardando serviço',succeeded:'Concluído',failed:'Falhou',uncertain:'Precisa de conferência',cancelled:'Encerrado',draft:'Rascunho',processing:'Preparando mídia',publishing:'Publicando',published:'Publicado'};
function markConnectionFormSaved(id){dirtyConnectionForms.delete(id);$('#setupUnsaved').hidden=!dirtyConnectionForms.size;}
function setSetupResult(id,kind,message){const el=$('#'+id);el.hidden=false;el.dataset.status=kind;el.textContent=message;}
function setSetupStep(step){for(let n=1;n<=3;n++){const el=$('#setupStep'+n);el.classList.toggle('current',n===step);el.classList.toggle('done',n<step);el.setAttribute?.('aria-current',n===step?'step':'false');}}
function friendlySetupError(message){if(/429|cota|limite temporário/i.test(message))return 'Sua cota ou limite de uso do Gemini foi atingido. Aguarde a renovação no Google AI Studio e tente novamente. Não é necessário cadastrar cartão.';if(/403|401|chave inválida|permissão/i.test(message))return 'O Google não aceitou esta chave ou o acesso ao projeto. Copie uma chave de API do Google AI Studio e confira as permissões. '+message;if(/404|modelo não/i.test(message))return 'Não foi possível acessar um modelo para sua conta. '+message;return message;}
function updateSpecialistKeyHelp(){renderCredentialLinks();if(!connectionData)return;const name=$('#agentKey').value,cred=connectionData.credentials.find(c=>c.name===name);$('#specialistKeyHelp').textContent=cred?.configured?'Já existe uma chave salva para este provedor. Deixe o campo vazio para mantê-la.':'Cadastre uma chave deste provedor para usar o especialista. A chave do Gemini não funciona em outros serviços.';}
function renderSetupSummary(d){const general=d.general_connection||{},profiles=d.profiles||[],statuses=state.connection_status||[],inherited=profiles.filter(p=>p.inherit).map(p=>p.employee),info=general.status?general:statuses.find(s=>inherited.includes(s.employee));const ready=info?.verified;
const badge=$('#setupConnectionBadge');badge.title=info?.checked?'Última confirmação: '+new Date(info.checked*1000).toLocaleString('pt-BR'):'';badge.textContent=ready?'● Conexão testada':info?.status==='configured'?'● Chave salva · teste pendente':'○ Conecte sua IA';badge.dataset.status=ready?'success':info?.status==='configured'?'pending':'empty';
const gatewayCredential=d.credentials.find(c=>c.name==='FREELLM_API_KEY');$('#freeLLMKey').placeholder=gatewayCredential?.configured?'Chave unificada salva — vazio reutiliza':'Copie do painel local da FreeLLMAPI';const credential=d.credentials.find(c=>c.name==='GEMINI_API_KEY');$('#setupKeyStatus').textContent=credential?.configured?'✓ Chave Gemini já salva':'Nenhuma chave Gemini salva';$('#quickGeminiKey').placeholder=credential?.configured?'Chave já salva — cole somente se quiser trocar':'Cole sua chave do Google AI Studio';
const targetKey=JSON.stringify(state.employees.map(e=>[e.id,e.name,e.role]));if(targetKey!==setupTargetSignature){setupTargetSignature=targetKey;const target=$('#setupEmployee').value;$('#setupEmployee').innerHTML='<option value="team">Equipe padrão (mantém especialistas)</option>'+state.employees.map(e=>`<option value="${e.id}">Somente ${esc(e.name)} · ${esc(e.role)}</option>`).join('');$('#setupEmployee').value=target==='team'||state.employees.some(e=>String(e.id)===target)?target:'team';}
const cardsKey=JSON.stringify([state.employees.map(e=>[e.id,e.name,e.role,e.color]),profiles,statuses]);if(cardsKey===setupTeamSignature)return;setupTeamSignature=cardsKey;
$('#setupTeamCards').innerHTML=state.employees.map(e=>{const p=profiles.find(p=>p.employee===e.id),s=statuses.find(s=>s.employee===e.id),status=s?.verified?'Conexão testada':s?.status==='configured'?'Chave salva':s?.status==='missing_key'?'Falta cadastrar chave':'Sem IA conectada';return `<article class="setup-member-card"><div class="member-avatar" style="--member-color:${esc(e.color)}">${esc(e.name.slice(0,1))}</div><div><strong>${esc(e.name)}</strong><small>${esc(e.role)}</small><span class="member-model">${p?.inherit?'Usa a IA padrão':'Modelo próprio'}</span><span class="member-connection" data-status="${s?.verified?'success':'pending'}">${status}</span></div><button type="button" data-setup-employee="${e.id}" aria-label="Configurar ${esc(e.name)}">Configurar</button></article>`;}).join('');
document.querySelectorAll('[data-setup-employee]').forEach(b=>b.onclick=()=>{if(dirtyConnectionForms.has('agentConnection'))return report({message:'Salve o funcionário que está editando antes de escolher outro.'});showConnectionTab('agents');$('#agentEmployee').value=b.dataset.setupEmployee;loadAgentProfile();});
}
