let researchSignature='';
function renderResearch(d){const people=d.profiles.filter(p=>p.tools.includes('research')).map(p=>state.employees.find(e=>e.id===p.employee)).filter(Boolean),prev=$('#researchEmployee').value;$('#researchEmployee').innerHTML=people.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');$('#researchEmployee').value=people.some(e=>String(e.id)===prev)?prev:String(people.find(e=>/marketing/i.test(e.role))?.id??people[0]?.id??'');$('#researchSubmit').disabled=!people.length;const jobs=d.jobs.filter(j=>j.kind==='research'),sig=JSON.stringify(jobs);if(sig===researchSignature)return;researchSignature=sig;$('#researchResults').innerHTML=jobs.map(j=>{let r={};try{r=JSON.parse(j.result||'{}')}catch(e){}return `<article class="knowledge-card"><small>Pesquisa #${j.id} · ${esc(connectionStatusLabels[j.status]||j.status)}</small><h3>${esc(r.query||'Tendências no Brasil')}</h3>${j.error?`<p class="error">${esc(j.error)}</p>`:''}${r.retrieved_at?`<p class="field-help">${esc(r.provider)} · consultado em ${esc(new Date(r.retrieved_at).toLocaleString('pt-BR'))}${r.cached?' · cache de até 10 minutos':''}</p>`:''}${(r.items||[]).map(i=>`<div class="research-source"><a href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">${esc(i.title)}</a><small>${esc(i.publisher)} · ${i.published?esc(new Date(i.published).toLocaleString('pt-BR')):'Data de publicação não informada'}</small><p>${esc(i.snippet)}</p>${i.observed_at?`<small>Observado pelo usuário em ${esc(i.observed_at)}</small>`:''}${i.statistics?`<small>Contadores acumulados: ${Object.entries(i.statistics).map(([k,v])=>esc(({views:'visualizações',likes:'curtidas',comments:'comentários'})[k]||k)+': '+Number(v).toLocaleString('pt-BR')).join(' · ')}</small>`:''}${i.reported_search_bucket?`<small>Faixa de buscas informada pelo feed: ${esc(i.reported_search_bucket)}</small>`:''}</div>`).join('')}${(r.sections||[]).map(s=>`<p class="radar-source-state"><b>${esc(s.platform)}</b> · ${esc(({available:'Disponível',empty:'Sem resultados',unavailable:'Indisponível'})[s.status]||s.status)}${s.message?' — '+esc(s.message):''}</p>`).join('')}${r.scope?`<p class="field-help">${esc(r.scope)}</p>`:''}${r.note?`<p class="field-help">${esc(r.note)}</p>`:''}</article>`}).join('')||'<p class="empty">Pesquisas e fontes aparecerão aqui. RSS não precisa de chave; charts do YouTube exigem a chave gratuita cadastrada acima.</p>';}
$('#researchForm').onsubmit=async e=>{e.preventDefault();$('#researchSubmit').disabled=true;try{await post('tools/job',{employee:+$('#researchEmployee').value,kind:'research',params:{query:$('#researchQuery').value,mode:$('#researchMode').value,days:+$('#researchDays').value||7,region:$('#radarRegion').value||'BR',category:$('#radarCategory').value||'0'}});$('#researchStatus').textContent='Pesquisa na fila. Retome a equipe e aguarde a pessoa chegar à mesa. O resultado aparecerá abaixo.';await loadConnections(false);}catch(e){$('#researchStatus').textContent=e.message;}finally{$('#researchSubmit').disabled=false;}};

