const credentialSources={
 GEMINI_API_KEY:[['https://aistudio.google.com/apikey','Obtenha sua chave no Google AI Studio']],
 FREELLM_API_KEY:[['http://127.0.0.1:3001','Obter chave no painel FreeLLMAPI'],['/tutorial-freellm.html','Vídeo e lista de APIs'],['https://github.com/tashfeenahmed/freellmapi/releases','Instalar FreeLLMAPI gratuita']],
 GROQ_API_KEY:[['https://console.groq.com/keys','Obtenha sua chave no GroqCloud']],
 OPENROUTER_API_KEY:[['https://openrouter.ai/settings/keys','Obtenha sua chave no OpenRouter']],
 YOUTUBE_API_KEY:[['https://console.cloud.google.com/apis/credentials','Criar chave no Google Cloud']],
 INSTAGRAM_TOKEN:[['https://developers.facebook.com/apps/','Obter token no aplicativo Meta / Instagram']],
 META_APP_SECRET:[['https://developers.facebook.com/apps/','Abrir aplicativo Meta para consultar o segredo']],
 STORAGE_KEY:[['https://supabase.com/dashboard','Abrir projeto Supabase e consultar as chaves']],
 OFFICE_API_KEY:[['https://aistudio.google.com/apikey','Google AI Studio'],['https://console.groq.com/keys','GroqCloud'],['https://openrouter.ai/settings/keys','OpenRouter']],
 CODER_API_KEY:[['https://aistudio.google.com/apikey','Google AI Studio'],['https://console.groq.com/keys','GroqCloud'],['https://openrouter.ai/settings/keys','OpenRouter']]
};
function credentialHelp(name){const links=credentialSources[name]||[];const notes={YOUTUBE_API_KEY:'Ative YouTube Data API v3 no projeto antes de usar a chave. Use a cota gratuita.',INSTAGRAM_TOKEN:'Selecione seu aplicativo, abra a configuração Instagram e gere um token oficial para a conta profissional. Não use sua senha.',META_APP_SECRET:'No aplicativo: Configurações → Básico → Segredo do aplicativo. Não é o token de publicação.',STORAGE_KEY:'Selecione o projeto → Settings → API Keys. Use uma credencial de servidor autorizada para upload; ela fica apenas no backend local.',OFFICE_API_KEY:'Escolha o mesmo provedor configurado para este modelo.',CODER_API_KEY:'Escolha o mesmo provedor configurado para o especialista.'};return `<span class="credential-links">${links.map(([url,label])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}${notes[name]?`<small>${notes[name]}</small>`:''}</span>`;}
function renderCredentialLinks(){for(const [input,output]of [['agentKey','specialistKeyLinks'],['generalKey','generalKeyLinks'],['con_instagram_key','instagramKeyLinks'],['con_instagram_secret','metaSecretLinks'],['con_storage_key','storageKeyLinks']]){const node=$('#'+output);if(node)node.innerHTML=credentialHelp($('#'+input).value);}}
for(const id of ['agentKey','generalKey','con_instagram_key','con_instagram_secret','con_storage_key'])$('#'+id).addEventListener?.('change',renderCredentialLinks);

