let accessDraft=new Map(),accessDirty=false,accessSignature='';
const accessProviders={freellm:'FreeLLMAPI',general:'IA padrão',gemini:'Gemini',groq:'Groq',openrouter:'OpenRouter'};
const accessResources={browser:'Navegar na web',research:'Web, livros e TV',youtube:'YouTube API',image:'Imagens por IA',video_local:'Edição e motion SaaS',video:'Vídeo por IA',instagram:'Instagram',art:'Arte local',code:'Executar código',board:'Quadro',objects:'Objetos',files:'Arquivos'};
function profileProvider(p){if(p.inherit)return 'general';return Object.entries(textPresets).find(([,v])=>v.base===p.base_url)?.[0]||'custom';}
function markAccessDirty(){accessDirty=true;$('#accessStatus').textContent='Alterações pendentes. Clique em Salvar acessos da equipe.';}
function chooseAccessProvider(employee,provider){const row=accessDraft.get(employee);if(!row)return;row.choice=provider;row.provider=provider===row.originalChoice?'keep':provider;markAccessDirty();drawAccessMatrix();}
function changeAccessResource(employee,key,checked){const row=accessDraft.get(employee);if(!row)return;if(key==='youtube'){row.youtube=checked;if(checked&&!row.tools.includes('research'))row.tools.push('research');}else{row.tools=row.tools.filter(t=>t!==key);if(checked)row.tools.push(key);if(key==='research'&&!checked)row.youtube=false;}markAccessDirty();}
function renderAccessMatrix(d){const sig=JSON.stringify(d.profiles.map(p=>[p.employee,p.access_version]));if(accessDirty||sig===accessSignature)return;accessSignature=sig;accessDraft=new Map(d.profiles.map(p=>[p.employee,{employee:p.employee,expected:p.access_version,provider:'keep',choice:profileProvider(p),originalChoice:profileProvider(p),tools:[...p.tools],youtube:!!p.youtube_allowed}]));drawAccessMatrix();}
function drawAccessMatrix(){const rows=[...accessDraft.values()];$('#accessMatrix').innerHTML=`<table class="access-table"><caption>Uma IA de texto por pessoa; recursos adicionais independentes</caption><thead><tr><th scope="col">Funcionário</th>${Object.entries(accessProviders).map(([key,label])=>`<th scope="col">${label}<button type="button" data-access-provider-all="${key}" aria-label="Aplicar ${label} a toda a equipe">Todos</button></th>`).join('')}${Object.entries(accessResources).map(([key,label])=>`<th scope="col">${label}<label class="access-all"><input type="checkbox" data-access-all="${key}" ${rows.every(r=>key==='youtube'?r.youtube:r.tools.includes(key))?'checked':''} aria-label="Marcar ou desmarcar ${label} para todos"> Todos</label></th>`).join('')}</tr></thead><tbody>${rows.map(r=>{const e=state.employees.find(e=>e.id===r.employee);return `<tr><th scope="row">${esc(e?.name||nameOf(r.employee))}<small>${esc(e?.role||'')}${r.choice==='custom'?' · Modelo próprio preservado':''}</small></th>${Object.entries(accessProviders).map(([key,label])=>`<td><input type="checkbox" data-access-person="${r.employee}" data-access-provider="${key}" ${r.choice===key?'checked':''} aria-label="${esc(e?.name)}: usar ${label}"></td>`).join('')}${Object.entries(accessResources).map(([key,label])=>`<td><input type="checkbox" data-access-person="${r.employee}" data-access-resource="${key}" ${(key==='youtube'?r.youtube:r.tools.includes(key))?'checked':''} aria-label="${esc(e?.name)}: permitir ${label}"></td>`).join('')}</tr>`;}).join('')}</tbody></table>`;document.querySelectorAll('[data-access-provider]').forEach(b=>b.onchange=()=>chooseAccessProvider(+b.dataset.accessPerson,b.dataset.accessProvider));document.querySelectorAll('[data-access-resource]').forEach(b=>b.onchange=()=>{changeAccessResource(+b.dataset.accessPerson,b.dataset.accessResource,b.checked);drawAccessMatrix();});document.querySelectorAll('[data-access-provider-all]').forEach(b=>b.onclick=()=>{for(const r of rows){r.choice=b.dataset.accessProviderAll;r.provider=r.choice===r.originalChoice?'keep':r.choice;}markAccessDirty();drawAccessMatrix();});document.querySelectorAll('[data-access-all]').forEach(b=>b.onchange=()=>{for(const r of rows)changeAccessResource(r.employee,b.dataset.accessAll,b.checked);drawAccessMatrix();});}
$('#accessSave').onclick=async()=>{if(dirtyConnectionForms.has('agentConnection')){$('#accessStatus').textContent='Salve primeiro as alterações do perfil individual avançado.';return;}if(!accessDirty){$('#accessStatus').textContent='Nenhuma alteração pendente.';return;}$('#accessSave').disabled=true;try{const rows=[...accessDraft.values()].map(({employee,expected,provider,tools,youtube})=>({employee,expected,provider,tools,youtube}));await post('integrations/access',{rows});accessDirty=false;accessSignature='';await loadConnections(false);if(connectionData){renderAccessMatrix(connectionData);loadAgentProfile();}$('#accessStatus').textContent='Acessos salvos para toda a equipe. Marcar acesso não testa a chave nem executa chamadas.';}catch(e){$('#accessStatus').textContent=e.message;}finally{$('#accessSave').disabled=false;}};
$('#accessReset').onclick=async()=>{accessDirty=false;accessSignature='';await loadConnections(false);if(connectionData)renderAccessMatrix(connectionData);$('#accessStatus').textContent='Alterações descartadas; matriz recarregada.';};

let videoScenes=[],videoStudioData=null,videoImportBusy=false,videoSubmitting=false,studioLimitsDirty=false;
const motionLabels={title:'Abertura',dashboard:'Tela do produto',features:'Benefícios',cta:'Chamada final'};
function videoPlan(){const plan={format:$('#videoFormat').value||'portrait',quality:$('#videoQuality').value||'720p',transition:$('#videoTransition').value||'cut',brand:{name:$('#videoBrand').value||'',background:$('#videoBackground').value||'#101b31',foreground:$('#videoForeground').value||'#f5f7fc',accent:$('#videoAccent').value||'#70e2bf'},scenes:videoScenes.map(s=>({...s}))};if(+$('#videoLogo').value)plan.logo_asset_id=+$('#videoLogo').value;if(+$('#videoAudio').value)plan.soundtrack={asset_id:+$('#videoAudio').value,volume:Number($('#videoAudioVolume').value||.25),start:Number($('#videoAudioStart').value||0),loop:$('#videoAudioLoop').checked};return plan;}
function renderVideoStudio(d){videoStudioData=d;if(!studioLimitsDirty){$('#studioLocalLimit').value=d.settings?.limits?.video_local??20;$('#studioRemoteLimit').value=d.settings?.limits?.video??2;}if(!$('#videoTimeline').innerHTML)renderVideoTimeline();const prev=$('#videoEmployee').value,people=state.employees.filter(e=>d.profiles.some(p=>p.employee===e.id&&p.tools.includes('video_local')));$('#videoEmployee').innerHTML=people.map(e=>`<option value="${e.id}">${esc(e.name)} · ${esc(e.role)}</option>`).join('');$('#videoEmployee').value=people.some(e=>String(e.id)===prev)?prev:String(people[0]?.id??'');$('#videoEngineStatus').textContent=d.video_local_installed?'FFmpeg e FFprobe encontrados. Motion e textos também precisam de Pillow.':'FFmpeg/FFprobe não encontrados. Instale com Instalar-video.bat e reinicie. Para motion, execute também Instalar-imagens.bat.';for(const [id,filter,empty]of [['videoSource',a=>a.mime.startsWith('image/')||a.mime==='video/mp4','Sem mídia'],['videoLogo',a=>a.mime.startsWith('image/'),'Sem logo'],['videoAudio',a=>a.mime.startsWith('audio/'),'Sem faixa adicional']]){const saved=$('#'+id).value,media=d.assets.filter(filter);$('#'+id).innerHTML=(id==='videoSource'?'':'<option value="">'+empty+'</option>')+media.map(a=>`<option value="${a.id}">#${a.id} · ${esc(a.filename)}</option>`).join('');if(media.some(a=>String(a.id)===saved))$('#'+id).value=saved;}$('#videoImportButton').disabled=videoImportBusy||!d.video_local_installed||!people.length;$('#videoSourcePreview').disabled=!d.assets.some(a=>a.mime.startsWith('image/')||a.mime==='video/mp4');updateVideoControls();const job=d.jobs.find(j=>['video_local','video'].includes(j.kind)&&String(j.employee)===$('#videoEmployee').value);$('#videoJobStatus').innerHTML=job?`<small>Último vídeo · #${job.id} · ${esc(connectionStatusLabels[job.status]||job.status)}</small>${['queued','running'].includes(job.status)?`<progress max="100" value="${Math.max(0,Math.min(100,Number(job.progress)||0))}"></progress><small>${job.kind==='video'?'Aguardando o provedor; pode levar minutos.':Math.round(Number(job.progress)||0)+'%'}${state.paused?' · equipe pausada':''}</small><button type="button" id="videoCancelCurrent">Cancelar vídeo</button>`:''}${job.error?`<p class="error">${esc(job.error)}</p>`:''}${job.status==='succeeded'?'<p>MP4 pronto na galeria. Use Ver ou Baixar.</p>':''}`:'';const cancel=$('#videoCancelCurrent');if(cancel&&job)cancel.onclick=()=>toolAction('cancel',job.id);$('#videoProjects').innerHTML=d.jobs.filter(j=>j.kind==='video_local'&&j.status==='succeeded').map(j=>`<button type="button" data-video-project="${j.id}">Reeditar projeto #${j.id} · ${esc(nameOf(j.employee))}</button>`).join('')||'<p class="field-help">Os projetos renderizados ficam disponíveis para reeditar.</p>';document.querySelectorAll('[data-video-project]').forEach(button=>button.onclick=()=>{try{const job=d.jobs.find(j=>j.id===+button.dataset.videoProject),result=JSON.parse(job.result);if(!result.edit_plan)throw Error('Este vídeo foi feito antes do projeto editável. Use o MP4 como mídia em uma nova montagem.');loadVideoPlan(result.edit_plan);}catch(error){$('#videoRenderStatus').textContent=error.message;}});renderRemoteVideo(d);}
function updateVideoControls(){const total=videoScenes.reduce((sum,s)=>sum+Number(s.duration||0),0),allowed=(videoStudioData?.profiles||[]).some(p=>String(p.employee)===$('#videoEmployee').value&&p.tools.includes('video_local'));$('#videoTotal').textContent=videoScenes.length+' cena(s) · '+total.toFixed(1).replace('.',',')+' s / 60 s';$('#videoRenderButton').disabled=videoSubmitting||!videoStudioData?.video_local_installed||!allowed||!videoScenes.length||!Number.isFinite(total)||total>60||videoScenes.some(s=>!Number.isFinite(s.duration)||s.duration<.5);$('#videoAddScene').disabled=!(videoStudioData?.assets||[]).some(a=>a.mime.startsWith('image/')||a.mime==='video/mp4')||videoScenes.length>=12;$('#videoAddMotion').disabled=videoScenes.length>=12;$('#videoAddDemo').disabled=videoScenes.length>8;}
function renderVideoTimeline(){$('#videoTimeline').innerHTML=videoScenes.map((s,i)=>{const motion=s.kind==='motion',a=videoStudioData?.assets.find(a=>a.id===s.asset_id),video=!motion&&a?.mime==='video/mp4';return `<article class="video-scene ${motion?'motion-scene':''}"><header><b><span class="scene-number">${i+1}</span> ${motion?'✦ '+esc(motionLabels[s.template]||'Motion'):esc(a?.filename||'Mídia #'+s.asset_id)}</b><div><button type="button" data-video-up="${i}" ${i===0?'disabled':''} aria-label="Mover cena para cima">↑</button><button type="button" data-video-down="${i}" ${i===videoScenes.length-1?'disabled':''} aria-label="Mover cena para baixo">↓</button><button type="button" data-video-remove="${i}" aria-label="Remover cena">×</button></div></header><label>Título<input data-scene-index="${i}" data-scene-key="title" maxlength="100" value="${esc(s.title||'')}" placeholder="Título da cena"></label><div class="form-row"><label>Duração de saída (s)<input data-scene-index="${i}" data-scene-key="duration" type="number" min="0.5" max="30" step="0.1" value="${esc(s.duration)}"></label>${motion?`<label>Layout<select data-scene-index="${i}" data-scene-key="template">${Object.entries(motionLabels).map(([key,label])=>`<option value="${key}" ${s.template===key?'selected':''}>${label}</option>`).join('')}</select></label>`:`<label>Início do corte (s)<input data-scene-index="${i}" data-scene-key="start" type="number" min="0" max="180" step="0.1" value="${esc(s.start||0)}" ${video?'':'disabled'}></label>`}</div><details><summary>Texto, imagem e ajustes da cena</summary><label>Subtítulo / legenda manual<textarea data-scene-index="${i}" data-scene-key="subtitle" maxlength="240">${esc(s.subtitle||'')}</textarea></label>${motion?`<label>Benefícios (um por linha, até 4)<textarea data-scene-index="${i}" data-scene-key="items">${esc((Array.isArray(s.items)?s.items:[]).join('\n'))}</textarea></label><label>Chamada para ação<input data-scene-index="${i}" data-scene-key="cta" maxlength="60" value="${esc(s.cta||'')}"></label><label>Captura real do produto (opcional)<select data-scene-index="${i}" data-scene-key="asset_id"><option value="">Sem captura — painel ilustrativo</option>${(videoStudioData?.assets||[]).filter(a=>a.mime.startsWith('image/')).map(a=>`<option value="${a.id}" ${s.asset_id===a.id?'selected':''}>#${a.id} ${esc(a.filename)}</option>`).join('')}</select></label><button type="button" data-motion-preview="${i}">Ver quadro da cena</button>`:`<div class="form-row"><label>Enquadramento<select data-scene-index="${i}" data-scene-key="fit"><option value="contain" ${s.fit!=='cover'?'selected':''}>Inteira, com margens</option><option value="cover" ${s.fit==='cover'?'selected':''}>Preencher, recortando</option></select></label>${video?`<label>Velocidade<select data-scene-index="${i}" data-scene-key="speed">${[.5,1,1.5,2].map(v=>`<option value="${v}" ${(s.speed||1)===v?'selected':''}>${v}×</option>`).join('')}</select></label><label>Volume<input data-scene-index="${i}" data-scene-key="volume" type="number" min="0" max="2" step="0.1" value="${esc(s.volume??1)}"></label><label><input type="checkbox" data-scene-index="${i}" data-scene-key="mute" ${s.mute?'checked':''}> Silenciar original</label>`:`<label>Câmera<select data-scene-index="${i}" data-scene-key="motion">${Object.entries({still:'Parada',zoom:'Zoom suave','pan-left':'Panorâmica à esquerda','pan-right':'Panorâmica à direita'}).map(([key,label])=>`<option value="${key}" ${(s.motion||'still')===key?'selected':''}>${label}</option>`).join('')}</select></label>`}</div>`}</details></article>`;}).join('')||'<div class="video-empty"><b>Conte sua história em cenas</b><p>Comece com um template motion ou importe seus arquivos. Você pode misturar os dois na mesma montagem.</p></div>';document.querySelectorAll('[data-scene-key]').forEach(input=>{const change=()=>{const scene=videoScenes[+input.dataset.sceneIndex],key=input.dataset.sceneKey;if(input.type==='checkbox')scene[key]=input.checked;else if(key==='items')scene[key]=input.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean).slice(0,4);else if(key==='asset_id'){if(input.value)scene.asset_id=+input.value;else delete scene.asset_id;}else scene[key]=['duration','start','speed','volume'].includes(key)?Number(input.value):input.value;updateVideoControls();};input.oninput=change;input.onchange=change;});for(const [attribute,delta]of [['up',-1],['down',1]])document.querySelectorAll('[data-video-'+attribute+']').forEach(button=>button.onclick=()=>{const i=+button.dataset[attribute==='up'?'videoUp':'videoDown'],j=i+delta;if(j>=0&&j<videoScenes.length)[videoScenes[i],videoScenes[j]]=[videoScenes[j],videoScenes[i]];renderVideoTimeline();});document.querySelectorAll('[data-video-remove]').forEach(button=>button.onclick=()=>{videoScenes.splice(+button.dataset.videoRemove,1);renderVideoTimeline();});document.querySelectorAll('[data-motion-preview]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{const plan=videoPlan();plan.scenes=[plan.scenes[+button.dataset.motionPreview]];plan.quality='480p';delete plan.soundtrack;const result=await post('video/preview',{employee:+$('#videoEmployee').value,plan});$('#motionPreview').src='data:'+result.mime+';base64,'+result.data;$('#motionPreview').hidden=false;$('#motionPreviewNote').textContent='Quadro de prévia. Movimentos, cursor, gráficos e entradas aparecem animados no MP4 renderizado.';}catch(error){$('#motionPreviewNote').textContent=error.message;}finally{button.disabled=false;}});updateVideoControls();}
function addMotion(template){if(videoScenes.length>=12)return;const presets={title:{title:'Sua operação em um só lugar',subtitle:'Menos tarefas repetitivas. Mais tempo para o que importa.'},dashboard:{title:'Tenha uma visão clara do negócio',subtitle:'Mostre uma captura do seu sistema ou use o painel ilustrativo.'},features:{title:'Uma rotina mais simples',items:['Organize suas informações','Acompanhe tarefas e prazos','Decida com mais clareza']},cta:{title:'Dê o próximo passo',subtitle:'Conheça os recursos da sua solução.',cta:'Saiba mais'}};videoScenes.push({kind:'motion',template,duration:4,...presets[template]});renderVideoTimeline();}
$('#videoAddMotion').onclick=()=>addMotion($('#motionTemplate').value||'title');$('#videoAddDemo').onclick=()=>{if(videoScenes.length>8)return;for(const template of Object.keys(motionLabels))addMotion(template);};
$('#videoAddScene').onclick=()=>{if(videoScenes.length>=12)return;const asset=videoStudioData?.assets.find(a=>a.id===+$('#videoSource').value);if(!asset||asset.mime.startsWith('audio/'))return;videoScenes.push({asset_id:asset.id,start:0,duration:3,motion:'still',mute:false});renderVideoTimeline();};$('#videoSourcePreview').onclick=()=>previewAsset(+$('#videoSource').value).catch(report);$('#videoEmployee').onchange=()=>{if(videoStudioData)renderVideoStudio(videoStudioData);};
$('#videoImport').onsubmit=async event=>{event.preventDefault();const file=$('#videoImportFile').files?.[0],employee=+$('#videoEmployee').value;if(!file){$('#videoImportStatus').textContent='Escolha uma imagem, vídeo ou áudio primeiro.';return;}videoImportBusy=true;$('#videoImportButton').disabled=true;try{if(file.size>20*1024*1024||!(/\.(png|jpe?g|webp|mp4|mp3|wav|m4a)$/i).test(file.name))throw Error('Use imagem, MP4, MP3, WAV ou M4A de até 20 MB.');$('#videoImportStatus').textContent='Importando e verificando a mídia…';const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(let i=0;i<bytes.length;i+=8192)raw+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await post('media/import',{employee,filename:file.name,data:btoa(raw)});$('#videoImportFile').value='';await loadConnections(false);$('#'+(result.mime?.startsWith('audio/')?'videoAudio':'videoSource')).value=String(result.asset_id);$('#videoImportStatus').textContent='Mídia importada como #'+result.asset_id+'. O original foi preservado.';}catch(error){$('#videoImportStatus').textContent=error.message;}finally{videoImportBusy=false;if(videoStudioData)renderVideoStudio(videoStudioData);}};
$('#videoRender').onsubmit=async event=>{event.preventDefault();videoSubmitting=true;updateVideoControls();try{await post('tools/job',{employee:+$('#videoEmployee').value,kind:'video_local',params:videoPlan()});$('#videoRenderStatus').textContent='Projeto na fila. Acompanhe a renderização; o MP4 e o plano editável serão preservados.';await loadConnections(false);}catch(error){$('#videoRenderStatus').textContent=error.message;}finally{videoSubmitting=false;updateVideoControls();}};
function loadVideoPlan(plan){if(!plan||!Array.isArray(plan.scenes)||!plan.scenes.length||plan.scenes.length>12)throw Error('Projeto de vídeo inválido.');const checked=JSON.parse(JSON.stringify(plan.scenes));if(checked.some(s=>!s||typeof s!=='object'||Array.isArray(s)||!Number.isFinite(s.duration)||s.duration<.5||s.duration>30||(s.start!==undefined&&(!Number.isFinite(s.start)||s.start<0||s.start>180))||(s.speed!==undefined&&(!Number.isFinite(s.speed)||s.speed<.5||s.speed>2))||(s.volume!==undefined&&(!Number.isFinite(s.volume)||s.volume<0||s.volume>2))||(s.items!==undefined&&(!Array.isArray(s.items)||s.items.some(item=>typeof item!=='string'))))||checked.reduce((sum,s)=>sum+s.duration,0)>60)throw Error('Revise as durações, os campos e o limite de 60 segundos do projeto.');videoScenes=checked;$('#videoFormat').value=plan.format||'portrait';$('#videoQuality').value=plan.quality||'720p';$('#videoTransition').value=plan.transition||'cut';$('#videoBrand').value=plan.brand?.name||'';$('#videoBackground').value=plan.brand?.background||'#101b31';$('#videoForeground').value=plan.brand?.foreground||'#f5f7fc';$('#videoAccent').value=plan.brand?.accent||'#70e2bf';$('#videoLogo').value=String(plan.logo_asset_id||'');$('#videoAudio').value=String(plan.soundtrack?.asset_id||'');$('#videoAudioVolume').value=plan.soundtrack?.volume??.25;$('#videoAudioStart').value=plan.soundtrack?.start||0;$('#videoAudioLoop').checked=!!plan.soundtrack?.loop;renderVideoTimeline();$('#videoRenderStatus').textContent='Projeto carregado. Ajuste as cenas e renderize uma nova versão; o MP4 anterior permanece salvo.';}
$('#videoExportPlan').onclick=()=>{const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(videoPlan(),null,2)],{type:'application/json'}));link.href=url;link.download='projeto-motion-atelie.json';link.click();URL.revokeObjectURL(url);};
$('#videoLoadPlan').onchange=async()=>{try{const file=$('#videoLoadPlan').files?.[0];if(!file)return;if(file.size>64000)throw Error('Projeto JSON acima de 64 KB.');loadVideoPlan(JSON.parse(await file.text()));}catch(error){$('#videoRenderStatus').textContent=error.message;}finally{$('#videoLoadPlan').value='';}};
function renderRemoteVideo(d){const prev=$('#remoteVideoEmployee').value,people=state.employees.filter(e=>d.profiles.some(p=>p.employee===e.id&&p.tools.includes('video')));$('#remoteVideoEmployee').innerHTML=people.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');$('#remoteVideoEmployee').value=people.some(e=>String(e.id)===prev)?prev:String(people[0]?.id??'');$('#remoteVideoSubmit').disabled=!people.length||d.settings?.video_gateway_enabled!=='yes';$('#remoteVideoConnection').textContent=d.settings?.video_gateway_enabled==='yes'?'Geração habilitada. Depende de modelo de vídeo, saldo/cota e provedor configurados na FreeLLMAPI.':'Desativada. Motion SaaS local e edição continuam disponíveis sem esse serviço.';if(!remoteVideoDirty)$('#remoteVideoEnabled').checked=d.settings?.video_gateway_enabled==='yes';}
