function renderBrowserStudio(d){const engine=d.browser||{installed:false,active:[],capacity:2},people=state.employees.filter(e=>d.profiles.some(p=>p.employee===e.id&&p.tools.includes('browser'))),previous=$('#browserEmployee').value;$('#browserEmployee').innerHTML=people.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('');$('#browserEmployee').value=people.some(e=>String(e.id)===previous)?previous:String(people[0]?.id??'');$('#browserSubmit').disabled=!engine.installed||!people.length;$('#browserEngine').textContent=engine.installed?`Chromium disponível · ${engine.active.length}/2 sessões ativas`:'Componente indisponível. No código-fonte, execute Instalar-navegador.bat. No app, gere uma nova versão com Chromium incluído.';const jobs=d.jobs.filter(j=>j.kind==='browser').slice(0,12);$('#browserSessions').innerHTML=jobs.map(j=>{const a=engine.active.find(a=>a.id===j.id);let label=connectionStatusLabels[j.status]||j.status;try{const r=JSON.parse(j.result||'{}');if(j.status==='succeeded'&&r.complete===false)label=r.outcome==='blocked'?'Pesquisa bloqueada':'Resultado parcial';}catch{}return `<article class="knowledge-card"><b>#${j.id} · ${esc(nameOf(j.employee))}</b><p>${esc(label)}${a?' · etapa '+a.step+' · '+esc(a.title):''}</p>${a?'<small>'+esc(a.url)+'</small>':''}${j.error?'<p>'+esc(j.error)+'</p>':''}<button data-browser-preview="${j.id}">Ver última captura</button>${['queued','running'].includes(j.status)?`<button data-browser-stop="${j.id}">Interromper</button>`:''}${j.result?`<button data-browser-report="${j.id}">Ler resultado e fontes</button>`:''}</article>`;}).join('')||'<p>As pesquisas aparecerão aqui.</p>';document.querySelectorAll('[data-browser-stop]').forEach(b=>b.onclick=async()=>{try{await post('tools/cancel',{id:+b.dataset.browserStop});await loadConnections(false);}catch(e){report(e);}});document.querySelectorAll('[data-browser-report]').forEach(b=>b.onclick=()=>{const j=jobs.find(j=>j.id===+b.dataset.browserReport);try{$('#browserReport').textContent=JSON.stringify(JSON.parse(j.result),null,2);}catch{$('#browserReport').textContent='Resultado indisponível.';}});document.querySelectorAll('[data-browser-preview]').forEach(b=>b.onclick=async()=>{try{const response=await fetch('/api/browser/preview?id='+b.dataset.browserPreview,{headers:{'X-Office-Token':state.token}});if(!response.ok)throw Error('A captura ainda não está disponível. Atualize após carregar uma página.');const blob=await response.blob();if(browserPreviewURL)URL.revokeObjectURL(browserPreviewURL);browserPreviewURL=URL.createObjectURL(blob);$('#browserPreview').src=browserPreviewURL;$('#browserPreview').hidden=false;}catch(e){report(e);}});}
